        verdict = "DO NOT GIVE HONEY"
    else:
        verdict = "Rule no longer applies at this age"
    print("Age %d months: %s" % (age_months, verdict))
print("Rule: no honey under 12 months, in any form.")

def abv(og, fg):
    return (og - fg) * 131.25


BATCHES = [("Signature yogurt base", None, None), ("Signature mead, light", 1.060, 1.012), ("Signature mead, strong", 1.090, 1.010)]
print("Fermentation estimates")
for name, og, fg in BATCHES:
    if og is None:
        print("%s: lactose to lactic acid, milk thickens as casein sets" % name)
    else:
        print("%s: OG %.3f, FG %.3f, estimated ABV %.1f%%" % (name, og, fg, abv(og, fg)))
print("ABV estimate rule: (OG - FG) x 131.25")

STAGES = [(110, "thread"), (115, "soft ball"), (121, "firm ball"), (127, "hard ball"), (138, "soft crack"), (149, "hard crack"), (170, "caramel")]


def stage_for(temp_c):
    found = "below thread"
    for mark, name in STAGES:
        if temp_c >= mark:
            found = name
    return found


print("Candy stage lookup")
for temp_c in [108, 112, 118, 150, 172]:
    print("%d degrees C: %s stage" % (temp_c, stage_for(temp_c)))
print("Maillard browning: sugars plus proteins, from about 140 degrees C")
print("Caramelization: sugar alone, at higher heat")
